describe('ToolRegistry.execute schema reuse', () => {
  afterEach(() => {
    jest.restoreAllMocks();
  });

  it('does not recompile a static inputSchema across ten execute calls', async () => {
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'get_weather',
        description: 'Get weather for a location',
        inputSchema: {
          type: 'object',
          properties: {location: {type: 'string'}},
          required: ['location'],
        },
      },
      async () => 'sunny'
    );
    const compile = jest.spyOn(Ajv.prototype, 'compile');

    for (let call = 0; call < 10; call += 1) {
      await registry.execute('get_weather', {location: 'Paris'});
    }

    expect(compile).toHaveBeenCalledTimes(0);
  });
});
EOF
